import{_ as e,c as a,b as n,o as s}from"./app-DKvarYBr.js";const o={};function p(r,t){return s(),a("div",null,t[0]||(t[0]=[n(`<p><strong><a href="https://route.com/" target="_blank" rel="noopener noreferrer">Route</a></strong>:- An android/iOS app that allows to virtually track the orders i.e. packages to be delivered. It enables package protection and one-click refunds and reorders.</p><p>Using the <a href="https://marketplace-doc.webkul.com/classic/Introduction/" target="_blank" rel="noopener noreferrer">Multi-vendor Marketplace app</a> for Shopify, you can allow customers to ensure their orders with <strong>Routes</strong>.</p><p>In Short, you can allow customers to enable insurance on product purchases and virtually track the packages to be shipped.</p><p>With the &quot;<strong>Route Insurance</strong>&quot; feature app, you can provide an &quot;Insurance&quot; option to the customers on the cart page.</p><p>Enabling the option, the customers need to pay the insurance amount configured via Route.</p><p>This feature app comes with the pricing of <strong>$7 USD/month</strong> in addition to your current Multi-vendor plan.</p><p><strong>MAKE A NOTE:-</strong></p><ul><li>Sellers won&#39;t be able to select the &quot;Insurance&quot; option on their products individually, but the option will be enabled for all the products.</li><li>&quot;Orders with Route Insurance&quot; will be created as draft orders in the app. So, if you charge insurance amount on order, discount coupons won&#39;t be applicable to the checkout page.</li></ul><h3 id="how-to-route-feature-app" tabindex="-1"><a class="header-anchor" href="#how-to-route-feature-app"><span>How to Route Feature App?</span></a></h3><p>To enable this feature app, first visit the Feature Apps section. Now, search for the &quot;<strong>Route Insurance</strong>&quot;.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Dashboard-Admin-2-1200x597.png" alt="Dashboard-Admin-2"></p><p>Now, activate the Route Insurance feature app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Screenshot-2020-10-07T105719.027.png" alt="Screenshot-2020-10-07T105719.027"></p><p>Click the “<strong>Enable</strong>” button.</p><h4 id="admin-end-configuration" tabindex="-1"><a class="header-anchor" href="#admin-end-configuration"><span><strong>ADMIN END CONFIGURATION</strong></span></a></h4><p>As soon as you activate this feature app, you need to visit the admin panel Configuration&gt;&gt;<strong>Route Insurance Configuration</strong>&gt;&gt;Enter Details&gt;&gt;Save.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Home-Admin-1-1200x597.png" alt="Home-Admin-1"></p><p>Enter the Route Insurance Details.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Add-Route-Configuration-Admin-1200x799.png" alt="Add-Route-Configuration-Admin"></p><h3 id="how-to-get-route-insurance-details" tabindex="-1"><a class="header-anchor" href="#how-to-get-route-insurance-details"><span>How to Get Route Insurance Details?</span></a></h3><p>To use this feature app, you need to have an account on <a href="https://dashboard.route.com/" target="_blank" rel="noopener noreferrer">Route</a>. Now, to get the details, you need to follow the below steps:-</p><ul><li>Firstly, login to Route: <a href="https://dashboard.route.com/login" target="_blank" rel="noopener noreferrer">https://dashboard.route.com/login</a></li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Route-1200x597.png" alt="Route"></p><ul><li>Visiting the Route Dashboard, go to the <strong>Admin</strong> menu.</li><li>In the Installation Details section, get the Public Token and Secret Token.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Route-1-1200x627.png" alt="Route-1"></p><p>Get the details and configure in the app.</p><p>Moreover, to make it work, You need to visit the Configuration&gt;&gt;<strong>Order Configuration</strong> menu and enable the &quot;Mandate Order Tranking Number&quot; tab.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Configuration-Admin-13-1200x627.png" alt="Configuration-Admin-13"></p><p>Now, to show the &quot;Insurance&quot; option on the cart page, you need to add the codes provided in the app.</p><h3 id="insurance-option-on-cart-page" tabindex="-1"><a class="header-anchor" href="#insurance-option-on-cart-page"><span>Insurance Option on Cart Page</span></a></h3><p>To show the &quot;Insurance&quot; option on the cart page, you need to get the codes provided in Configuration&gt;&gt;Instruction for Marketplace menu and add the codes to the store theme liquid file.</p><p>To Display Insurance Model on Cart Page, copy the below code as first line in <strong>cart.liquid:</strong>-</p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>header</span><span class="token punctuation">&gt;</span></span> <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://cdn.routeapp.io/route-widget/stable/route-widget-stable.min.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span> <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>header</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Copy following code into <strong>cart.liquid (or cart-template.liquid,</strong> if exist) template above the checkout button:-</p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>RouteWidget<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>To Display Insurance Model at Customers/Order Page, copy the following code as first-line in <strong>customers/order.liquid.</strong></p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>header</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://route-cdn.s3.amazonaws.com/route-widget-shopify/route-widget-static.min.js<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>header</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Copy following code into <strong>customers/order.liquid</strong> template, After your order details tabel code:</p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>route-div<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Once done, the &quot;Insurance&quot; option will be visible to the customers on the cart page.</p><h2 id="how-does-it-work-for-customers" tabindex="-1"><a class="header-anchor" href="#how-does-it-work-for-customers"><span>How does it work for Customers?</span></a></h2><p>As soon as customers will choose the &quot;Insurance&quot; option (a toggle checker) on the cart page, they will be able to view the price and then, will proceed for checkout.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Your-Shopping-Cart-–-JohnDoe2-1200x597.png" alt="Your-Shopping-Cart-–-JohnDoe2"></p><p>Now, once the customer enables the toggle checker on the cart page, a custom product gets added as insurance with some amount added to the total order amount.</p><p>Let say, Insurance amount is $5 then, a custom product with $5 gets added to the cart.</p><p>You will be able to view that custom product on the order details page in their backend and can easily recognize the insurance amount.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/10/Information-JohnDoe2-Checkout-1200x597.png" alt="Information-JohnDoe2-Checkout"></p><p>This is how the Route Insurance Feature App works.</p><h2 id="demo-details" tabindex="-1"><a class="header-anchor" href="#demo-details"><span>Demo Details</span></a></h2><p>You can check the demo of the Multivendor Marketplace App for Shopify: <a href="https://multivendor-marketplace-5.myshopify.com/pages/seller-profile" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/pages/seller-profile</a></p>`,50)]))}const l=e(o,[["render",p]]),c=JSON.parse('{"path":"/zenith/Featured-App/Marketplace%20Miscellaneous%20Add-ons/ROUTE%20INSURANCE.html","title":"Route Insurance","lang":"en-US","frontmatter":{"title":"Route Insurance","description":"Route Insurance","date":"2025-07-25T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"How to Route Feature App?","slug":"how-to-route-feature-app","link":"#how-to-route-feature-app","children":[]},{"level":3,"title":"How to Get Route Insurance Details?","slug":"how-to-get-route-insurance-details","link":"#how-to-get-route-insurance-details","children":[]},{"level":3,"title":"Insurance Option on Cart Page","slug":"insurance-option-on-cart-page","link":"#insurance-option-on-cart-page","children":[]},{"level":2,"title":"How does it work for Customers?","slug":"how-does-it-work-for-customers","link":"#how-does-it-work-for-customers","children":[]},{"level":2,"title":"Demo Details","slug":"demo-details","link":"#demo-details","children":[]}],"git":{"updatedTime":1764586065000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":2,"url":"https://github.com/pratik"}],"changelog":[{"hash":"6da5a1c75e37f77fbe87cc39a942e54bbc8e175a","time":1764586065000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflict"},{"hash":"bbe1b03e5e919255cadeb8590203b7f1b2e7378e","time":1757583088000,"email":"pratik@webkul.com","author":"pratik","message":"add some new file"}]},"filePathRelative":"zenith/Featured-App/Marketplace Miscellaneous Add-ons/ROUTE INSURANCE.md"}');export{l as comp,c as data};
